for f, pos in POS.items():
    p = f'{proj}/{f}.dc.html'
    t = open(p).read()
    for cond, (aria, body) in bodies(SEGW).items():
        if ('<sc-if value="{{%s}}"' % cond) not in t:
            k = t.index('<sc-if value="{{isPace}}"')
            t = t[:k] + '<sc-if value="{{%s}}"></sc-if>\n' % cond + t[k:]
        a = t.index('<sc-if value="{{%s}}"' % cond)
        # find matching close: count nested sc-if
        i = a; depth = 0
        while True:
            o = t.find('<sc-if', i); c = t.find('</sc-if>', i)
            if o != -1 and o < c: depth += 1; i = o + 6
            else:
                depth -= 1; i = c + 8
                if depth == 0: break
        t = t[:a] + panel(cond, aria, pos[cond], body) + t[i:]
    ov = '<sc-if value="{{playing}}" hint-placeholder-val="{{false}}">\n<button type="button" aria-label="Stop, and show the controls" onClick="{{togglePlay}}" style="position: absolute; inset: 0; border: 0; padding: 0; background: transparent; cursor: pointer; z-index: 40"></button>\n</sc-if>\n'
    assert ov in t
    t = t.replace(ov, '')
    scr = {'R3Laptop': '<div style="position: absolute; left: 217.7px; top: 124.6px; width: 1710px; height: 904px;', 'R3Phone': '<div style="position: absolute; left: 24px; top: 23px; width: 402px; height: 874px;'}[f]
    assert t.count(scr) == 1, f
    t = t.replace(scr, scr.replace('<div style=', '<div onClick="{{tapScreen}}" style='))
    t = t.replace('...KB_VALS,', '...KB_VALS,\n...PANEL_VALS,')
    drop = ('paceLabel:', 'ownPace: [', 'speeds:', 'handItems:', 'other: s.other', 'versions:', 'metro: s.metro')
    L = t.split('\n'); out = []; skip = False
    for l in L:
        if l.startswith('ownPace: ['): skip = True; continue
        if skip:
            if l.startswith('].map((i) =>'): skip = False
            continue
        if l.startswith(drop): continue
        out.append(l)
    t = '\n'.join(out)
    r = t.index('const VIEWS = [')
    t = t[:r] + JS.replace('SHEET_GRAB', "'block'" if f == 'R3Phone' else "'none'") + t[r:]
    open(p, 'w').write(t)
    print(f, 'ok')
